    let mbx = BackendArg::from("mr-boxington");
    if !tools.iter().any(|tool| tool.ba().short == mbx.short || tool.ba().full() == mbx.full()) {
        eyre::bail!("rust's mr_boxington option requires mr-boxington in [tools]; add `mr-boxington = \\\"latest\\\"`");
    }
    wrappers.insert("cargo".into(), CommandWrapper::Detailed(CommandWrapperOptions {
        command: "mbx".into(),
        args: Vec::new(),
        env: [("MBX_CARGO_SHIM_MODE".into(), "1".into())].into(),
    }));
    Ok(())
}
